#include <iostream>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    if (n % 2 == 0) {
        cout << n / 2;
        return 0;
    }

    ll divisor = n;
    for (ll i = 3; i <= n / i; i += 2) {
        if (n % i == 0) {
            divisor = i;
            break;
        }
    }

    cout << 1 + (n - divisor) / 2;
    return 0;
}

